goalkeeper:
// Easy Bot goalkeeper: hold the goal line on the ball owner -> goal centre
// axis, i.e. stand where that segment crosses the keeper's line so the mouth
// stays covered behind the carrier. Shade to the ball itself when it is
// loose or already between the keeper and the goal. Clear short toward
// midfield in possession.
function update(game) {
  const { me, ball } = game;
  const home = me.team === 'home';
  const lineX = home ? 5 : 95;
  const goalCenterX = home ? 0 : 100;

  if (me.hasBall) {
    me.shoot(68, 26, 0.9);
    return;
  }

  // The axis starts at the ball owner (either team) or the ball when free.
  let source = null;
  if (ball.owner !== null) {
    const [ownerTeam, ownerSlot] = ball.owner.split('-');
    const roster = ownerTeam === me.team ? game.teammates : game.opponents;
    const owner = roster.find((player) => player.slot === Number(ownerSlot));
    if (owner) source = owner.position;
  }
  if (source === null) source = ball.position;

  // Intersect the source -> goal centre segment with the keeper's line.
  let targetY = 25;
  const deltaX = goalCenterX - source.x;
  const crossing = deltaX === 0 ? -1 : (lineX - source.x) / deltaX;
  if (crossing > 0) {
    targetY = source.y + crossing * (25 - source.y);
  } else {
    // Source on the goal-centre vertical, or already between the keeper and
    // the goal: fall back to shading toward the ball itself.
    targetY = ball.position.y;
  }
  me.moveToward(lineX, Math.max(15, Math.min(35, targetY)));
}

defender1:
// Easy Bot defender (low side): hold a fixed depth between the ball and the
// own goal, track the ball inside the slot's assigned band, chase the ball
// when closest in the own half. In possession, clear short to the
// crowd's edge so the loose ball is contested rather than running a
// breakaway.
function update(game) {
  const { me, ball } = game;
  const home = me.team === 'home';
  const ownGoalX = home ? 0 : 100;
  const depthX = home ? 20 : 80;
  const ownHalf = home ? ball.position.x < 50 : ball.position.x > 50;

  if (me.hasBall) {
    me.shoot(68, 32, 0.9);
    return;
  }

  if (ownHalf && me.isClosestToBall()) {
    me.moveToward(ball.position.x, ball.position.y);
    return;
  }

  const bandMin = me.slot === 3 ? 25 : 5;
  const bandMax = me.slot === 2 ? 25 : 45;
  const targetY = Math.max(bandMin, Math.min(bandMax, ball.position.y));
  me.moveToward(depthX, targetY);
}

defender2:
// Easy Bot defender (high side): hold a fixed post at (depthX, 34) instead of
// tracking the ball, so the high flank stays open for opponent breakaways.
// In possession, always clear long to the far flank.
function update(game) {
  const { me, ball } = game;
  const home = me.team === 'home';
  const depthX = home ? 20 : 80;
  const postY = 30;

  if (me.hasBall) {
    me.shoot(68, 18, 0.9);
    return;
  }

  me.moveToward(depthX, postY);
}

attacker1:
// Easy Bot attacker: hold the kickoff anchor and only chase the ball once it
// is already deep in the attacking third. In possession, dribble at the goal
// and shoot at the near corner of the goal mouth from inside 11 units.
function update(game) {
  const { me, ball } = game;
  const home = me.team === 'home';
  const attackGoalX = home ? 100 : 0;
  const deepAttack = home ? ball.position.x > 65 : ball.position.x < 35;

  if (me.hasBall) {
    const distanceToGoal = Math.abs(me.position.x - attackGoalX);
    if (distanceToGoal < 11) {
      me.shoot(attackGoalX, ball.position.y <= 25 ? 16 : 34, 0.45);
    } else {
      me.dribble(attackGoalX, 25);
    }
    return;
  }

  if (deepAttack) {
    me.moveToward(ball.position.x, ball.position.y);
    return;
  }

  // Hold the kickoff anchor otherwise (slot 4 top line, slot 5 bottom line).
  const anchorY = me.slot === 5 ? 35 : 15;
  me.moveToward(home ? 40 : 60, anchorY);
}

